package com.foxtrotalpha.reelsblocker.detectorimport android.graphics.Rectimport android.view.accessibility.AccessibilityNodeInfo/** * Detects Instagram Reels via Instagram's internal view IDs. * * Instagram internally calls Reels "clips". Every immersive Reels player — * the Reels tab, For You / Explore reels, and reels opened from DMs or links — * is hosted inside a view with the ID `clips_viewer_view_pager`. Stories use a * completely different set of view IDs (`reel_viewer_*`, confusingly), so they * never match this check. * * Note: recent Instagram builds keep the clips viewer node in the tree at all * times with zero size, so a match requires `isVisibleToUser` and non-zero * on-screen bounds. */object ReelsDetector {    data class Result(        val shouldBlock: Boolean,        val reason: Reason? = null,    ) {        enum class Reason {            REEL_PLAYER_VISIBLE,            REELS_TAB_SELECTED,        }    }    private const val CLIPS_VIEWER_VIEW_ID =        "com.instagram.android:id/clips_viewer_view_pager"    private const val BOTTOM_REGION_RATIO = 0.18f    fun evaluate(root: AccessibilityNodeInfo?): Result {        if (root == null) {            return Result(shouldBlock = false)        }        if (isReelPlayerVisible(root)) {            return Result(shouldBlock = true, reason = Result.Reason.REEL_PLAYER_VISIBLE)        }        // Fallback in case Instagram renames the clips viewer ID: the selected        // "Reels" tab in the bottom navigation bar.        if (isReelsTabActive(root)) {            return Result(shouldBlock = true, reason = Result.Reason.REELS_TAB_SELECTED)        }        return Result(shouldBlock = false)    }    /**     * True when a Reels player (clips viewer) is actually on screen.     */    fun isReelPlayerVisible(root: AccessibilityNodeInfo): Boolean {        val nodes = root.findAccessibilityNodeInfosByViewId(CLIPS_VIEWER_VIEW_ID) ?: return false        return nodes.any { node ->            val bounds = Rect()            node.getBoundsInScreen(bounds)            node.isVisibleToUser && bounds.width() > 0 && bounds.height() > 0        }    }    fun isReelsTabActive(root: AccessibilityNodeInfo): Boolean {        val reelsTab = findSelectedNavTab(root, "Reels") ?: return false        return isInBottomRegion(reelsTab, root)    }    fun findSelectedNavTab(root: AccessibilityNodeInfo, label: String): AccessibilityNodeInfo? {        val tab = findNavTab(root, label) ?: return null        if (!tab.isSelected || !isInBottomRegion(tab, root)) {            return null        }        return tab    }    fun findNavTab(root: AccessibilityNodeInfo, label: String): AccessibilityNodeInfo? {        var found: AccessibilityNodeInfo? = null        walkTree(root) { node ->            if (found != null) {                return@walkTree true            }            if (!node.isClickable || node.isEditable) {                return@walkTree false            }            val description = node.contentDescription?.toString()?.trim().orEmpty()            if (description.equals(label, ignoreCase = true)) {                found = node                true            } else {                false            }        }        return found    }    private fun isInBottomRegion(node: AccessibilityNodeInfo, root: AccessibilityNodeInfo): Boolean {        val rootRect = Rect()        val nodeRect = Rect()        root.getBoundsInScreen(rootRect)        node.getBoundsInScreen(nodeRect)        if (rootRect.height() <= 0) {            return false        }        val bottomThreshold = rootRect.bottom - (rootRect.height() * BOTTOM_REGION_RATIO).toInt()        return nodeRect.centerY() >= bottomThreshold    }    private fun walkTree(        node: AccessibilityNodeInfo?,        predicate: (AccessibilityNodeInfo) -> Boolean,    ): Boolean {        if (node == null) {            return false        }        if (predicate(node)) {            return true        }        for (index in 0 until node.childCount) {            if (walkTree(node.getChild(index), predicate)) {                return true            }        }        return false    }}